namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int CapCents = 2_000;
    private const int MinimumSubtotalCents = 3_000;

    public static int DiscountCents(LoyaltyTier tier, int subtotalCents) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, CapCents);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
EOF
cat > CheckoutPricing.Domain/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int DiscountCents(string? code, int remainingCents) =>
        code?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeFiveCents,
            "SUMMER10" => Math.Min(remainingCents / 10, SummerTenCapCents),
            _ => 0
        };
}
EOF
cat > CheckoutPricing.Domain/ShippingFeePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFeeCents(tier) : StandardFeeCents(payableTotalCents, tier);

    private static int ExpressFeeCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFeeCents(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}
EOF
